#include <metal_stdlib>
using namespace metal;

// A six-second Halloween postcard: every shape and light is drawn here.
struct ShaderUniforms {
    float4 resolutionTime;
    float4 mouse;
};

constant float PI = 3.14159265358979323846;

float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}

float noise2(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(i), hash21(i + float2(1.0, 0.0)), f.x),
               mix(hash21(i + float2(0.0, 1.0)),
                   hash21(i + float2(1.0, 1.0)), f.x), f.y);
}

float segmentDistance(float2 p, float2 a, float2 b) {
    float2 v = b - a;
    return length(p - (a + v * clamp(dot(p - a, v) / dot(v, v), 0.0, 1.0)));
}

float boxDistance(float2 p, float2 halfSize) {
    float2 d = abs(p) - halfSize;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

float webSilk(float2 p, float side, float time) {
    // The left corner owns a broad web; the right is a smaller echo of it.
    float webScale = side < 0.0 ? 1.28 : 0.70;
    float2 q = (p - float2(side * 0.89, 0.51)) / webScale;
    q.x *= -side;
    if (q.x < 0.0 || q.y > 0.0) return 0.0;
    float r = length(q);
    if (r > 0.56 || r < 0.025) return 0.0;
    float angle = atan2(-q.y, q.x);
    if (angle > PI * 0.5) return 0.0;
    float ray = r * abs(sin(angle * 16.0)) / 16.0;
    float strand = 1.0 - smoothstep(0.0010, 0.0028, ray);
    float sector = fract(angle * 16.0 / PI);
    float scallop = 0.016 * sin(sector * PI);
    float ring = abs(sin(PI * (r + scallop) / 0.073)) * 0.073 / PI;
    float ringLine = (1.0 - smoothstep(0.0010, 0.0027, ring))
                   * smoothstep(0.045, 0.075, r);
    float glint = 0.65 + 0.35 * sin(2.2 * time + 12.0 * r + side);
    return max(strand, ringLine) * glint;
}

float spiderShape(float2 p, float time) {
    float sway = 0.012 * sin(1.8 * time);
    float2 c = float2(-0.57 + sway, 0.18 + 0.035 * sin(1.35 * time));
    float silkThread = 1.0 - smoothstep(0.001, 0.0028,
        segmentDistance(p, float2(-0.57, 0.43), c + float2(0.0, 0.021)));
    float body = 1.0 - smoothstep(0.96, 1.08,
        length((p - c) / float2(0.025, 0.032)));
    float head = 1.0 - smoothstep(0.92, 1.08,
        length((p - c - float2(0.0, 0.030)) / float2(0.015, 0.014)));
    float legs = 0.0;
    for (int i = 0; i < 4; ++i) {
        float y = 0.017 - float(i) * 0.011;
        float reach = 0.048 - float(i) * 0.003;
        for (int s = -1; s <= 1; s += 2) {
            float side = float(s);
            float2 a = c + float2(side * 0.012, y);
            float2 b = c + float2(side * 0.030, y + 0.018 - 0.010 * float(i));
            float2 d = c + float2(side * reach, y - 0.018);
            float line = min(segmentDistance(p, a, b), segmentDistance(p, b, d));
            legs = max(legs, 1.0 - smoothstep(0.0010, 0.0026, line));
        }
    }
    return max(silkThread * 0.55, max(body, max(head, legs)));
}

float eyeShape(float2 q, float x) {
    float y = q.y - 0.07;
    float width = 0.16 * (0.21 - y) / 0.24;
    float d = max(abs(q.x - x) - width, max(-0.03 - y, y - 0.21));
    return 1.0 - smoothstep(-0.012, 0.012, d);
}

float lobeDistance(float2 q, float2 center, float2 radii) {
    return length((q - center) / radii) - 1.0;
}

float3 drawPumpkin(float2 p, float2 center, float scale,
                   float time, float seed, float3 under) {
    float2 q = (p - center) / scale;
    if (abs(q.x) > 2.2 || abs(q.y) > 2.2) return under;
    float flicker = 0.82 + 0.13 * sin(time * 10.0 + seed * 4.0)
                    + 0.05 * sin(time * 23.0 + seed);
    float halo = exp(-dot(q / float2(1.30, 1.05),
                          q / float2(1.30, 1.05)) * 2.0);
    under += float3(0.24, 0.075, 0.008) * halo * flicker;

    float stemLean = 0.04 + 0.13 * (q.y - 0.70);
    float stem = 1.0 - smoothstep(-0.025, 0.025,
        boxDistance(q - float2(stemLean, 0.76), float2(0.075, 0.24)));
    under = mix(under, float3(0.20, 0.29, 0.075), stem);
    float curl = 1.0 - smoothstep(0.020, 0.045,
        segmentDistance(q, float2(0.08, 0.94), float2(0.34, 1.03)));
    under = mix(under, float3(0.31, 0.39, 0.10), curl);

    // Five uneven overlapping ribs give it shoulders, a stem dip and a
    // flattened, tapered base instead of the outline of a round ball.
    float d = lobeDistance(q, float2(0.00, -0.05), float2(0.43, 0.66));
    d = min(d, lobeDistance(q, float2(-0.35, -0.07), float2(0.43, 0.70)));
    d = min(d, lobeDistance(q, float2(0.34, -0.05), float2(0.44, 0.69)));
    d = min(d, lobeDistance(q, float2(-0.66, -0.10), float2(0.33, 0.54)));
    d = min(d, lobeDistance(q, float2(0.65, -0.09), float2(0.34, 0.55)));
    float body = 1.0 - smoothstep(-0.018, 0.018, d);
    float seam = exp(-pow((abs(q.x) - 0.25) / 0.042, 2.0))
               + exp(-pow((abs(q.x) - 0.59) / 0.048, 2.0));
    float bulge = exp(-pow(q.x / 0.22, 2.0))
                + 0.65 * exp(-pow((abs(q.x) - 0.43) / 0.18, 2.0));
    float shade = clamp(0.86 + 0.13 * q.y + 0.09 * bulge
                        - 0.21 * seam - 0.25 * smoothstep(-0.22, 0.02, d),
                        0.44, 1.15);
    float3 orange = float3(0.94, 0.29, 0.045) * shade;
    orange += float3(0.16, 0.044, 0.006) * exp(-pow((q.x + 0.32) * 3.0, 2.0));
    orange *= 0.94 + 0.10 * noise2(q * 11.0 + seed);

    float eyes = max(eyeShape(q, -0.31), eyeShape(q, 0.31));
    float nose = eyeShape(q - float2(0.0, -0.18), 0.0) * 0.75;
    float mouth = 1.0 - smoothstep(0.91, 1.04,
        length((q - float2(0.0, -0.34)) / float2(0.55, 0.25)));
    mouth *= 1.0 - smoothstep(-0.20, -0.15, q.y);
    float teeth = 1.0 - smoothstep(-0.015, 0.015,
        min(boxDistance(q - float2(-0.19, -0.30), float2(0.050, 0.09)),
            boxDistance(q - float2(0.18, -0.39), float2(0.052, 0.075))));
    mouth *= 1.0 - teeth;
    float face = clamp(max(eyes, max(nose, mouth)), 0.0, 1.0);
    orange = mix(orange, float3(1.0, 0.77, 0.20) * flicker, face);
    orange += float3(0.28, 0.10, 0.0) * flicker *
              exp(-9.0 * (q.x * q.x + (q.y + 0.12) * (q.y + 0.12)));
    return mix(under, orange, body);
}

float3 drawCandy(float2 p, float time, float3 under) {
    for (int i = 0; i < 18; ++i) {
        float n = float(i);
        float seed = hash21(float2(n, 4.7));
        float speed = 0.095 + 0.060 * hash21(float2(n, 8.1));
        float fall = fract(seed + time * speed);
        float2 center = float2(-0.89 + 1.78 * hash21(float2(n, 13.2))
                                  + 0.045 * sin(time * 1.3 + n),
                               0.58 - 1.18 * fall);
        float size = 0.014 + 0.012 * hash21(float2(n, 21.4));
        float2 delta = p - center;
        if (abs(delta.x) > 2.0 * size || abs(delta.y) > 2.0 * size)
            continue;
        float a = time * (0.8 + seed) + n;
        float2 q = float2(cos(a) * delta.x + sin(a) * delta.y,
                          -sin(a) * delta.x + cos(a) * delta.y) / size;
        float mask;
        float3 candy;
        if (i % 3 == 0) {
            float width = 0.50 * (1.0 - q.y);
            float edge = max(abs(q.x) - width, max(-1.0 - q.y, q.y - 1.0));
            mask = 1.0 - smoothstep(-0.08, 0.08, edge);
            candy = q.y > 0.35 ? float3(1.0, 0.92, 0.71)
                    : (q.y > -0.30 ? float3(1.0, 0.40, 0.08)
                                     : float3(1.0, 0.78, 0.12));
        } else {
            float centerPiece = 1.0 - smoothstep(0.91, 1.05,
                length(q / float2(0.57, 0.47)));
            float wing = 1.0 - smoothstep(-0.05, 0.07,
                max(0.55 - abs(q.x), max(abs(q.x) - 1.05,
                    abs(q.y) - (0.43 - 0.21 * (abs(q.x) - 0.55)))));
            mask = max(centerPiece, wing);
            float stripe = 0.5 + 0.5 * cos(q.x * 12.0 + n);
            candy = (i % 2 == 0 ? float3(0.99, 0.18, 0.43)
                                : float3(0.37, 0.91, 0.70));
            candy = mix(candy, float3(1.0, 0.91, 0.75), stripe * 0.30);
            candy *= 0.76 + 0.20 * q.y;
        }
        under = mix(under, candy, mask * 0.95);
    }
    return under;
}

float3 halloweenScene(float2 p, float2 resolution, float time) {
    float sky = smoothstep(-0.48, 0.48, p.y);
    float3 color = mix(float3(0.16, 0.065, 0.20),
                       float3(0.025, 0.033, 0.105), sky);
    float cloud = noise2(float2(p.x * 3.0 + time * 0.028,
                                p.y * 6.0)) * 0.07;
    color += float3(0.30, 0.10, 0.28) * cloud;

    // The moon blooms against the sky; three distant lightning bursts flare.
    float moonD = length(p - float2(0.43, 0.25));
    color += float3(0.23, 0.20, 0.30) * exp(-pow(moonD / 0.23, 2.0));
    float moon = 1.0 - smoothstep(0.090, 0.097, moonD);
    color = mix(color, float3(0.89, 0.83, 0.66), moon);
    color -= float3(0.07, 0.055, 0.04) * moon
             * exp(-pow(length((p - float2(0.40, 0.28)) / 0.033), 2.0));
    float flash = 0.70 * exp(-pow((time - 1.14) / 0.075, 2.0));
    flash += exp(-pow((time - 3.39) / 0.065, 2.0));
    flash += 0.48 * exp(-pow((time - 3.54) / 0.055, 2.0));
    flash += 0.82 * exp(-pow((time - 5.20) / 0.080, 2.0));
    color += float3(0.30, 0.25, 0.43) * flash
             * (0.48 + 0.52 * exp(-pow((p.x + 0.20) / 0.55, 2.0)));
    float boltDistance = segmentDistance(p, float2(-0.17, 0.49), float2(-0.24, 0.30));
    boltDistance = min(boltDistance,
        segmentDistance(p, float2(-0.24, 0.30), float2(-0.15, 0.20)));
    boltDistance = min(boltDistance,
        segmentDistance(p, float2(-0.15, 0.20), float2(-0.20, 0.03)));
    color += float3(0.31, 0.29, 0.53) * flash
             * exp(-pow(boltDistance / 0.047, 2.0));
    color = mix(color, float3(0.89, 0.85, 1.0),
                (1.0 - smoothstep(0.002, 0.006, boltDistance)) * flash);

    float2 starCell = floor((p + float2(0.92, 0.48)) * 50.0);
    float2 starLocal = fract((p + float2(0.92, 0.48)) * 50.0) - 0.5;
    float starSeed = hash21(starCell);
    float star = (1.0 - smoothstep(0.012, 0.092, length(starLocal)))
                 * step(0.972, starSeed) * (0.5 + 0.5 * sin(time * 2.0 + starSeed * 19.0));
    color += float3(0.60, 0.68, 0.82) * star;

    float hillY = -0.35 + 0.035 * sin(p.x * 6.0 + 0.5)
                       + 0.020 * sin(p.x * 14.0);
    float hill = 1.0 - smoothstep(hillY - 0.006, hillY + 0.006, p.y);
    color = mix(color, float3(0.035, 0.048, 0.075), hill);
    color += float3(0.11, 0.09, 0.17) * flash * hill;
    float fog = exp(-pow((p.y + 0.33 - 0.022 * sin(p.x * 8.0 + time * 0.5)) / 0.10, 2.0));
    color += float3(0.10, 0.064, 0.13) * fog * 0.32;

    float silk = max(webSilk(p, -1.0, time), webSilk(p, 1.0, time));
    color = mix(color, float3(0.66, 0.72, 0.77), silk * 0.79);
    color = mix(color, float3(0.011, 0.012, 0.026), spiderShape(p, time));

    color = drawPumpkin(p, float2(-0.47, -0.30), 0.20, time, 0.5, color);
    color = drawPumpkin(p, float2(0.47, -0.30), 0.18, time, 1.8, color);
    color = drawPumpkin(p, float2(0.00, -0.32), 0.29, time, 3.1, color);
    color = drawCandy(p, time, color);

    // Rising colored motes swell and blink, with tiny cross-shaped glints.
    for (int i = 0; i < 32; ++i) {
        float n = float(i);
        float seed = hash21(float2(n, 51.0));
        float rise = fract(hash21(float2(n, 76.0)) + time * (0.08 + 0.035 * seed));
        float2 mote = float2(-0.79 + 1.58 * seed
                            + 0.036 * sin(time * 1.7 + n * 2.2),
                            -0.38 + 0.79 * rise);
        float2 delta = p - mote;
        if (abs(delta.x) > 0.065 || abs(delta.y) > 0.065) continue;
        float d = length(delta);
        float pulse = 0.48 + 0.52 * sin(time * 3.4 + n * 3.2);
        float3 tint = i % 3 == 0 ? float3(0.44, 0.31, 0.92)
                    : (i % 3 == 1 ? float3(1.0, 0.58, 0.13)
                                  : float3(0.31, 0.88, 0.72));
        color += tint * exp(-pow(d / 0.023, 2.0)) * pulse * 0.34;
        color += tint * exp(-pow(d / 0.0045, 2.0)) * pulse * 0.79;
        float cross = exp(-abs(delta.x) / 0.0022 - abs(delta.y) / 0.023)
                    + exp(-abs(delta.y) / 0.0022 - abs(delta.x) / 0.023);
        color += tint * cross * pulse * 0.23;
    }
    float2 vignetteUV = p / float2(resolution.x / resolution.y * 0.5, 0.5);
    float vignette = 1.0 - 0.20 * smoothstep(0.35, 1.3, length(vignetteUV));
    return clamp(color * vignette, float3(0.0), float3(1.0));
}

vertex float4 fullscreenVertex(uint vertexID [[vertex_id]]) {
    float2 p = float2((vertexID << 1) & 2, vertexID & 2);
    return float4(p * 2.0 - 1.0, 0.0, 1.0);
}

fragment float4 halloweenFragment(
    float4 position [[position]], constant ShaderUniforms &uniforms [[buffer(0)]]) {
    float2 resolution = uniforms.resolutionTime.xy;
    float2 frag = float2(position.x, resolution.y - position.y);
    float2 screen = (frag - 0.5 * resolution) / resolution.y;
    return float4(halloweenScene(screen, resolution,
                                 uniforms.resolutionTime.z), 1.0);
}
